// M59 / D-070: the nine roster datasheets generated by tools/fetch_bsdata.py at BSData 0f90355, checked
// against the New Recruit roster exports in docs/datasheets/ (stats, InSv, base, every weapon profile with
// its abilities, composition and model types). Where the two differ, BSData wins (D-070 lists each case).

#include <gtest/gtest.h>

#include <algorithm>
#include <map>
#include <optional>
#include <string>
#include <vector>

#include "core/data/datasheet.hpp"
#include "test_helpers.hpp"

using namespace wh40k::core;
using wh40k::test::in;
using wh40k::test::repo_root;

namespace {

const Datasheet& sheet(const std::string& file) {
    // Kept alive (std::map nodes don't move) so references into a sheet stay valid within a test.
    static std::map<std::string, Datasheet> cache;
    auto it = cache.find(file);
    if (it == cache.end()) {
        it = cache.emplace(file, load_datasheet(repo_root() / ("data/units/" + file + ".json"))).first;
    }
    return it->second;
}

struct Stats {
    int m_in;
    int t;
    int sv;
    std::optional<int> insv;
    int w;
    int ld;
    int oc;
};

void expect_stats(const ModelTypeSheet& mt, const Stats& s) {
    SCOPED_TRACE(mt.name);
    const Characteristics& c = mt.characteristics;
    ASSERT_TRUE(c.move_mm.has_value());
    EXPECT_FLOAT_EQ(*c.move_mm, in(static_cast<float>(s.m_in)));
    EXPECT_EQ(c.toughness, s.t);
    EXPECT_EQ(c.save, s.sv);
    EXPECT_EQ(c.invuln_save, s.insv);
    EXPECT_EQ(c.wounds, s.w);
    EXPECT_EQ(c.leadership, s.ld);
    EXPECT_EQ(c.objective_control, s.oc);
}

const ModelTypeSheet& type_of(const Datasheet& ds, const char* name) {
    const ModelTypeSheet* mt = ds.find_model_type(name);
    if (mt == nullptr) throw std::logic_error(std::string("no model type ") + name);
    return *mt;
}

Base round_base(float mm) { return Base{BaseShape::Round, mm, 0.0f}; }

struct Prof {
    const char* name;
    WeaponKind kind;
    std::optional<int> range_in;  // nullopt for melee
    DiceExpr a;
    std::optional<int> skill;
    int s;
    int ap;
    DiceExpr d;
    std::vector<WeaponAbility> abilities;
};

void expect_weapon(const Datasheet& ds, const char* weapon, const std::vector<Prof>& profiles) {
    SCOPED_TRACE(std::string(ds.name) + " / " + weapon);
    const Weapon* w = ds.find_weapon(weapon);
    ASSERT_NE(w, nullptr);
    ASSERT_EQ(w->profiles.size(), profiles.size());
    for (std::size_t i = 0; i < profiles.size(); ++i) {
        const WeaponProfile& p = w->profiles[i];
        const Prof& e = profiles[i];
        EXPECT_EQ(p.name, e.name);
        EXPECT_EQ(p.kind, e.kind);
        if (e.range_in) {
            ASSERT_TRUE(p.range_mm.has_value());
            EXPECT_FLOAT_EQ(*p.range_mm, in(static_cast<float>(*e.range_in)));
        } else {
            EXPECT_FALSE(p.range_mm.has_value());
        }
        EXPECT_EQ(p.attacks, e.a);
        EXPECT_EQ(p.skill, e.skill);
        EXPECT_EQ(p.strength, e.s);
        EXPECT_EQ(p.armour_penetration, e.ap);
        EXPECT_EQ(p.damage, e.d);
        EXPECT_EQ(p.abilities, e.abilities);
    }
}

DiceExpr fixed(int v) { return DiceExpr::fixed(v); }
constexpr WeaponKind R = WeaponKind::Ranged;
constexpr WeaponKind M = WeaponKind::Melee;
const std::nullopt_t melee = std::nullopt;

bool has_keyword(const Datasheet& ds, const char* k) {
    return std::find(ds.keywords.begin(), ds.keywords.end(), k) != ds.keywords.end();
}

bool has_ability_text(const Datasheet& ds, const char* name) {
    return std::any_of(ds.abilities.begin(), ds.abilities.end(), [&](const AbilityText& a) { return a.name == name; });
}

}  // namespace

// ---- Tyranids ----

TEST(R02_Datasheet, HiveTyrantMatchesTheRoster) {
    const Datasheet& ds = sheet("hive_tyrant");
    EXPECT_EQ(ds.name, "Hive Tyrant");
    EXPECT_EQ(ds.source_commit, "0f9035541630ae6d83869bab34b63d909767d081");
    EXPECT_EQ(ds.faction_keywords, (std::vector<std::string>{"Tyranids"}));
    EXPECT_TRUE(has_keyword(ds, "Monster"));
    EXPECT_TRUE(has_keyword(ds, "Character"));
    EXPECT_TRUE(has_keyword(ds, "Synapse"));
    EXPECT_TRUE(has_ability_text(ds, "Onslaught (Aura, Psychic)"));
    EXPECT_TRUE(has_ability_text(ds, "Will of the Hive Mind"));
    // 02.06 / D-070: a single model is 1-1.
    EXPECT_EQ(ds.min_models, 1);
    EXPECT_EQ(ds.max_models, 1);
    ASSERT_EQ(ds.model_types.size(), 1u);
    const ModelTypeSheet& mt = type_of(ds, "Hive Tyrant");
    EXPECT_EQ(mt.min, 1);
    EXPECT_EQ(mt.max, 1);
    expect_stats(mt, {8, 10, 2, 4, 10, 7, 3});
    EXPECT_EQ(mt.base, round_base(60.0f));
    // D-070: wargear two groups deep, defaults from the required groups.
    EXPECT_EQ(mt.default_weapons,
              (std::vector<std::string>{"Monstrous bonesword and lash whip", "Monstrous scything talons"}));
    EXPECT_EQ(mt.weapon_options, (std::vector<std::string>{"Heavy venom cannon", "Monstrous bonesword and lash whip",
                                                          "Monstrous scything talons", "Stranglethorn cannon"}));
    expect_weapon(ds, "Monstrous bonesword and lash whip",
                  {{"Monstrous bonesword and lash whip", M, melee, fixed(6), 2, 9, -2, fixed(3), {ability::TwinLinked{}}}});
    expect_weapon(ds, "Monstrous scything talons",
                  {{"Monstrous scything talons", M, melee, fixed(4), 2, 7, -2, fixed(2), {ability::ExtraAttacks{}}}});
    expect_weapon(ds, "Heavy venom cannon", {{"Heavy venom cannon", R, 36, DiceExpr{1, 3, 0}, 2, 9, -2, fixed(3),
                                              {ability::Blast{1}}}});
    expect_weapon(ds, "Stranglethorn cannon", {{"Stranglethorn cannon", R, 36, DiceExpr{1, 6, 1}, 2, 7, -1, fixed(2),
                                                {ability::Blast{1}}}});
}

TEST(R02_Datasheet, TermagantsStillMatchTheRoster) {
    // The roster's Termagants: 10 with fleshborers (the V1 file, unchanged by M59).
    const Datasheet& ds = sheet("termagants");
    EXPECT_EQ(ds.min_models, 10);
    EXPECT_EQ(ds.max_models, 20);
    const ModelTypeSheet& mt = type_of(ds, "Termagants");
    expect_stats(mt, {6, 3, 5, std::nullopt, 1, 8, 2});
    EXPECT_EQ(mt.base, round_base(28.5f));
    expect_weapon(ds, "Fleshborer", {{"Fleshborer", R, 18, fixed(1), 4, 5, 0, fixed(1), {ability::Assault{}}}});
    expect_weapon(ds, "Chitinous claws and teeth",
                  {{"Chitinous claws and teeth", M, melee, fixed(1), 4, 3, 0, fixed(1), {}}});
}

TEST(R02_Datasheet, GenestealersMatchTheRoster) {
    const Datasheet& ds = sheet("genestealers");
    EXPECT_EQ(ds.name, "Genestealers");
    EXPECT_TRUE(has_keyword(ds, "Infantry"));
    EXPECT_TRUE(has_ability_text(ds, "Vanguard Predator"));
    // D-070: the constraints sit on the model, not on a group.
    EXPECT_EQ(ds.min_models, 5);
    EXPECT_EQ(ds.max_models, 10);
    ASSERT_EQ(ds.model_types.size(), 1u);
    const ModelTypeSheet& mt = type_of(ds, "Genestealer");
    EXPECT_EQ(mt.min, 5);
    EXPECT_EQ(mt.max, 10);
    expect_stats(mt, {8, 4, 5, 5, 2, 7, 1});
    EXPECT_EQ(mt.base, round_base(32.0f));
    EXPECT_EQ(mt.default_weapons, (std::vector<std::string>{"Genestealers claws and talons"}));
    expect_weapon(ds, "Genestealers claws and talons",
                  {{"Genestealers claws and talons", M, melee, fixed(4), 2, 4, -2, fixed(1), {}}});
}

TEST(R02_Datasheet, TyrantGuardMatchTheRoster) {
    const Datasheet& ds = sheet("tyrant_guard");
    EXPECT_EQ(ds.min_models, 3);
    EXPECT_EQ(ds.max_models, 6);
    const ModelTypeSheet& mt = type_of(ds, "Tyrant Guard");
    EXPECT_EQ(mt.min, 3);
    EXPECT_EQ(mt.max, 6);
    expect_stats(mt, {6, 8, 3, std::nullopt, 4, 8, 1});
    EXPECT_EQ(mt.base, round_base(50.0f));
    EXPECT_EQ(mt.default_weapons, (std::vector<std::string>{"Scything talons and rending claws"}));
    EXPECT_EQ(mt.weapon_options,
              (std::vector<std::string>{"Bone cleaver, lash whip and rending claws", "Crushing claws and rending claws",
                                        "Scything talons and rending claws"}));
    expect_weapon(ds, "Scything talons and rending claws",
                  {{"Scything talons and rending claws", M, melee, fixed(5), 3, 5, -1, fixed(1), {}}});
    expect_weapon(ds, "Bone cleaver, lash whip and rending claws",
                  {{"Bone cleaver, lash whip and rending claws", M, melee, fixed(3), 3, 5, -1, fixed(2), {}}});
    expect_weapon(ds, "Crushing claws and rending claws",
                  {{"Crushing claws and rending claws", M, melee, fixed(2), 4, 8, -2, fixed(2), {ability::TwinLinked{}}}});
}

TEST(R02_Datasheet, ScreamerKillerMatchesTheRoster) {
    const Datasheet& ds = sheet("screamer_killer");
    EXPECT_EQ(ds.name, "Screamer-killer");
    EXPECT_TRUE(has_keyword(ds, "Monster"));
    EXPECT_TRUE(has_ability_text(ds, "Death Scream"));
    EXPECT_EQ(ds.min_models, 1);
    EXPECT_EQ(ds.max_models, 1);
    const ModelTypeSheet& mt = type_of(ds, "Screamer-killer");
    EXPECT_EQ(mt.min, 1);
    EXPECT_EQ(mt.max, 1);
    expect_stats(mt, {8, 9, 2, std::nullopt, 10, 8, 3});
    EXPECT_EQ(mt.base, round_base(90.0f));
    // D-070: min-1 entries inside a Wargear group without constraints are the default loadout.
    EXPECT_EQ(mt.default_weapons, (std::vector<std::string>{"Bio-plasmic scream", "Screamer-killer talons"}));
    expect_weapon(ds, "Bio-plasmic scream", {{"Bio-plasmic scream", R, 18, DiceExpr{1, 6, 3}, 4, 8, -2, fixed(1),
                                              {ability::Assault{}, ability::Blast{1}}}});
    expect_weapon(ds, "Screamer-killer talons",
                  {{"Screamer-killer talons", M, melee, fixed(10), 3, 10, -2, fixed(3), {}}});
}

TEST(R02_Datasheet, TyrannofexMatchesTheRosterWithAnOvalBase) {
    const Datasheet& ds = sheet("tyrannofex");
    EXPECT_TRUE(has_ability_text(ds, "Resilient Organism"));
    EXPECT_EQ(ds.min_models, 1);
    EXPECT_EQ(ds.max_models, 1);
    const ModelTypeSheet& mt = type_of(ds, "Tyrannofex");
    expect_stats(mt, {9, 12, 2, std::nullopt, 16, 8, 5});
    // D-070: "120x92mm" is an oval: diameter_mm is the width (92), length_mm the length (120).
    EXPECT_EQ(mt.base, (Base{BaseShape::Oval, 92.0f, 120.0f}));
    EXPECT_EQ(mt.default_weapons, (std::vector<std::string>{"Powerful limbs", "Stinger salvoes", "Fleshborer hive"}));
    expect_weapon(ds, "Stinger salvoes", {{"Stinger salvoes", R, 24, fixed(8), 3, 5, 0, fixed(1), {}}});
    expect_weapon(ds, "Fleshborer hive",
                  {{"Fleshborer hive", R, 24, fixed(20), 3, 5, 0, fixed(1),
                    {ability::Heavy{}, ability::SustainedHits{1}, ability::TwinLinked{}}}});
    expect_weapon(ds, "Powerful limbs", {{"Powerful limbs", M, melee, fixed(4), 3, 8, 0, fixed(2), {}}});
}

// ---- Chaos Space Marines ----

TEST(R02_Datasheet, ChaosLordMatchesTheRoster) {
    const Datasheet& ds = sheet("chaos_lord");
    EXPECT_EQ(ds.faction_keywords, (std::vector<std::string>{"Heretic Astartes"}));
    EXPECT_TRUE(has_keyword(ds, "Character"));
    EXPECT_TRUE(has_keyword(ds, "Infantry"));
    EXPECT_TRUE(has_ability_text(ds, "Chance for Glory"));
    EXPECT_EQ(ds.min_models, 1);
    EXPECT_EQ(ds.max_models, 1);
    const ModelTypeSheet& mt = type_of(ds, "Chaos Lord");
    expect_stats(mt, {6, 5, 3, 4, 5, 6, 1});
    EXPECT_EQ(mt.base, round_base(40.0f));
    // BSData's default is the daemon hammer; the roster takes the chainblade (a wargear option).
    EXPECT_EQ(mt.default_weapons, (std::vector<std::string>{"Daemon hammer", "Plasma pistol"}));
    EXPECT_EQ(mt.weapon_options, (std::vector<std::string>{"Accursed weapon", "Astartes chainblade", "Daemon hammer",
                                                          "Plasma pistol", "Power fist"}));
    expect_weapon(ds, "Plasma pistol",
                  {{"Plasma pistol - standard", R, 12, fixed(1), 2, 7, -2, fixed(1), {ability::CloseQuarters{}}},
                   {"Plasma pistol - supercharge", R, 12, fixed(1), 2, 8, -3, fixed(2),
                    {ability::Hazardous{}, ability::CloseQuarters{}}}});
    expect_weapon(ds, "Astartes chainblade", {{"Astartes chainblade", M, melee, fixed(7), 2, 5, -1, fixed(1), {}}});
}

TEST(R02_Datasheet, LegionariesMatchTheRosterWithTheChampionCounted) {
    const Datasheet& ds = sheet("legionaries");
    EXPECT_TRUE(has_keyword(ds, "Battleline"));
    EXPECT_TRUE(has_ability_text(ds, "Veterans of the Long War"));
    // D-070: the Aspiring Champion sits outside the 4-9 group: 5-10 models.
    EXPECT_EQ(ds.min_models, 5);
    EXPECT_EQ(ds.max_models, 10);
    const ModelTypeSheet& champ = type_of(ds, "Aspiring Champion");
    EXPECT_EQ(champ.min, 1);
    EXPECT_EQ(champ.max, 1);
    const ModelTypeSheet& chain = type_of(ds, "Legionary w/ chainsword");
    const ModelTypeSheet& bolt = type_of(ds, "Legionary w/ boltgun");
    EXPECT_EQ(chain.min, 0);
    EXPECT_EQ(chain.max, 9);
    EXPECT_EQ(bolt.max, 9);
    for (const ModelTypeSheet* mt : {&champ, &chain, &bolt}) {
        expect_stats(*mt, {6, 5, 3, std::nullopt, 2, 6, 2});
        EXPECT_EQ(mt->base, round_base(32.0f));
    }
    // D-070: the Champion's wargear sits in a Wargear group with "replace" groups inside; weapons behind
    // infoLinks (Bolt pistol, Astartes chainsword) are read.
    EXPECT_EQ(champ.default_weapons, (std::vector<std::string>{"Close combat weapon", "Bolt pistol", "Boltgun"}));
    EXPECT_NE(std::find(champ.weapon_options.begin(), champ.weapon_options.end(), "Astartes chainsword"),
              champ.weapon_options.end());
    EXPECT_EQ(chain.default_weapons,
              (std::vector<std::string>{"Astartes chainsword", "Bolt pistol", "Close combat weapon"}));
    EXPECT_EQ(bolt.default_weapons, (std::vector<std::string>{"Boltgun", "Bolt pistol", "Close combat weapon"}));
    expect_weapon(ds, "Bolt pistol",
                  {{"Bolt pistol", R, 12, fixed(1), 3, 5, -1, fixed(1), {ability::CloseQuarters{}}}});
    expect_weapon(ds, "Boltgun", {{"Boltgun", R, 24, fixed(2), 3, 5, -1, fixed(1), {}}});
    expect_weapon(ds, "Close combat weapon", {{"Close combat weapon", M, melee, fixed(3), 3, 5, 0, fixed(1), {}}});
    expect_weapon(ds, "Astartes chainsword", {{"Astartes chainsword", M, melee, fixed(4), 3, 5, -1, fixed(1), {}}});
}

TEST(R02_Datasheet, ChaosTerminatorsMatchTheRosterWithTheChampionCounted) {
    const Datasheet& ds = sheet("chaos_terminator_squad");
    EXPECT_TRUE(has_keyword(ds, "Terminator"));
    EXPECT_TRUE(has_ability_text(ds, "Despoilers"));
    EXPECT_EQ(ds.min_models, 5);
    EXPECT_EQ(ds.max_models, 10);
    const ModelTypeSheet& champ = type_of(ds, "Terminator Champion");
    const ModelTypeSheet& trooper = type_of(ds, "Accursed weapon and combi-bolter");
    EXPECT_EQ(champ.min, 1);
    EXPECT_EQ(champ.max, 1);
    EXPECT_EQ(trooper.max, 9);
    for (const ModelTypeSheet* mt : {&champ, &trooper}) {
        expect_stats(*mt, {5, 6, 2, 4, 3, 6, 1});
        EXPECT_EQ(mt->base, round_base(40.0f));
    }
    // D-070: the Champion's default is three levels deep (Wargear > "Combi-bolter and accursed weapon" >
    // one group per weapon).
    EXPECT_EQ(champ.default_weapons, (std::vector<std::string>{"Accursed weapon", "Combi-bolter"}));
    EXPECT_EQ(trooper.default_weapons, (std::vector<std::string>{"Combi-bolter", "Accursed weapon"}));
    expect_weapon(ds, "Combi-bolter", {{"Combi-bolter", R, 24, fixed(2), 3, 5, -1, fixed(1), {ability::RapidFire{2}}}});
    expect_weapon(ds, "Accursed weapon", {{"Accursed weapon", M, melee, fixed(4), 3, 5, -2, fixed(1), {}}});
}

TEST(R02_Datasheet, HavocsMatchTheRosterWithTheChampionCounted) {
    const Datasheet& ds = sheet("havocs");
    EXPECT_TRUE(has_ability_text(ds, "Stabilisation Talons"));
    // D-070: the Champion plus a 4-4 group: 5-5.
    EXPECT_EQ(ds.min_models, 5);
    EXPECT_EQ(ds.max_models, 5);
    const ModelTypeSheet& champ = type_of(ds, "Havoc Champion");
    const ModelTypeSheet& las = type_of(ds, "Havoc w/ lascannon");
    EXPECT_EQ(champ.min, 1);
    EXPECT_EQ(champ.max, 1);
    EXPECT_EQ(las.min, 0);
    EXPECT_EQ(las.max, 4);
    for (const ModelTypeSheet* mt : {&champ, &las}) {
        expect_stats(*mt, {5, 5, 3, std::nullopt, 3, 6, 1});
        EXPECT_EQ(mt->base, round_base(40.0f));
    }
    EXPECT_EQ(las.default_weapons, (std::vector<std::string>{"Havoc lascannon", "Close combat weapon"}));
    expect_weapon(ds, "Havoc lascannon", {{"Havoc lascannon", R, 48, fixed(1), 3, 12, -3, DiceExpr{1, 6, 1}, {}}});
    expect_weapon(ds, "Plasma gun",
                  {{"Plasma gun - standard", R, 24, fixed(1), 3, 7, -2, fixed(1), {ability::RapidFire{1}}},
                   {"Plasma gun - supercharge", R, 24, fixed(1), 3, 8, -3, fixed(2),
                    {ability::Hazardous{}, ability::RapidFire{1}}}});
    // D-070: BSData sets the shared Astartes chainsword profile's A to 5 inside a HAVOCS unit (a modifier
    // the tool applies); the roster shows A5 too. Legionaries keep A4.
    expect_weapon(ds, "Astartes chainsword", {{"Astartes chainsword", M, melee, fixed(5), 3, 5, -1, fixed(1), {}}});
    expect_weapon(ds, "Close combat weapon", {{"Close combat weapon", M, melee, fixed(3), 3, 5, 0, fixed(1), {}}});
}

TEST(R02_Datasheet, NoRosterSheetHasConditionalProfiles) {
    for (const char* f : {"hive_tyrant", "genestealers", "tyrant_guard", "screamer_killer", "tyrannofex", "chaos_lord",
                          "legionaries", "chaos_terminator_squad", "havocs", "termagants", "intercessor_squad"}) {
        EXPECT_TRUE(sheet(f).conditional_profiles.empty()) << f;
    }
}
